# 跨平台 sed 原地编辑（兼容 macOS BSD sed）
sed_i() {
    if [[ "$OSTYPE" == "darwin"* ]]; then
        sed -i '' "$@"
    else
        sed -i "$@"
    fi
}

# sed 替换串转义（使用 | 作为分隔符时）
escape_for_sed() {
    printf '%s' "$1" | sed 's/[&|\\"]/\\&/g'
}

# 从 .env 读取单个键的值
get_env_value() {
    local key=$1
    if [ ! -f .env ]; then
        return 0
    fi

    local line
