# 生成随机密钥
generate_secret() {
    if command -v openssl &> /dev/null; then
        openssl rand -base64 32
    else
        cat /dev/urandom | tr -dc 'a-zA-Z0-9' | fold -w 32 | head -n 1
    fi
}

# 跨平台 sed 原地编辑（兼容 macOS BSD sed）
sed_i() {
    if [[ "$OSTYPE" == "darwin"* ]]; then
        sed -i '' "$@"
    else
        sed -i "$@"
    fi
}

# sed 替换串转义（使用 | 作为分隔符时）
escape_for_sed() {
    printf '%s' "$1" | sed 's/[&|\\"]/\\&/g'
}

# 从 .env 读取单个键的值
get_env_value() {
    local key=$1
    if [ ! -f .env ]; then
        return 0
    fi

    local line
    line=$(grep -E "^${key}=" .env | tail -n 1 || true)
    if [ -z "$line" ]; then
        return 0
    fi

    local value="${line#*=}"
    value="${value%\"}"
    value="${value#\"}"
    printf '%s' "$value"
}

